I'm trying to make a Pong game using the HTML canvas element. I already animated the ball bouncing off the walls, but I'm stuck on how to add the paddle. What I want is a rectangle that's a little wider than the ball. When the user moves their mouse left or right, the paddle should move with it without them having to click anything. Here's what I have so far:

<script>
    class BouncingCanvas {
        constructor(args) {
            Object.assign(this, args);
            this.canvas = document.getElementById(this.canvas_id);
            this.ball_x = this.ball_y = this.ball_radius;

            window.requestAnimationFrame(this.draw);
        }

        checkForBounce = () => {
            if (this.ball_x + this.ball_radius >= this.canvas.width || this.ball_x - this.ball_radius <= 0) {
                this.x_movement_rate = this.x_movement_rate * -1;
            }

            if (this.ball_y + this.ball_radius >= this.canvas.height || this.ball_y - this.ball_radius <= 0) {
                this.y_movement_rate = this.y_movement_rate * -1;
            }
        }

        draw = () => {
            let ctx = this.canvas.getContext("2d");

            ctx.fillStyle = "blue";
            ctx.fillRect(0, 0, this.canvas.width, this.canvas.height);

            ctx.fillStyle = "green";
            ctx.translate(this.x_movement_rate, this.y_movement_rate);

            ctx.beginPath();
            ctx.arc(this.ball_radius, this.ball_radius, this.ball_radius, 0, 2 * Math.PI);
            ctx.fill();

            this.ball_x += this.x_movement_rate;
            this.ball_y += this.y_movement_rate;

            this.checkForBounce();

            window.requestAnimationFrame(this.draw);
        }
    }

    bc = new BouncingCanvas({'canvas_id': 'animation_canvas', 'ball_radius': 50, 'x_movement_rate': 4, 'y_movement_rate': 3});
  </script>
